import { endpoint, event, invoke, machine, mutation, on, query, ui } from '@hozu/core'
import { z } from 'zod'
import { home, login } from '../../routes.ts'

export const Session = z.object({ user: z.string() })
export const Name = z.object({ name: z.string().regex(/^\s*[A-Za-z]{2,20}\s*$/, 'Use 2–20 letters') })

export const SignIn = event({ payload: z.object({ name: z.string() }) })
export const SignOut = event({ payload: z.object({}) })
export const DeleteAccount = event({ payload: z.object({}) })

export const me = query({
  input: z.object({}),
  output: z.object({ name: z.string() }),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  runs: 'server',
})

// `/` only sends the visitor on: to the notes when signed in, to the sign-in page otherwise.
export const start = endpoint({ method: 'GET', path: '/', input: z.object({}), output: 'redirect' })

export const signIn = mutation({ input: Name, output: z.object({}), runs: 'server' })
export const signOut = mutation({ input: z.object({}), output: z.object({}), runs: 'server' })
// Deletes every note of the signed-in user (archived ones included), forgets the user and signs out.
export const deleteAccount = mutation({ input: z.object({}), output: z.object({}), runs: 'server' })

export const accountMachine = machine({
  context: z.object({
import { ui } from '@hozu/core'
import { admin } from '../../routes.ts'
import { me } from '../account/model.ts'
import { listUsers } from './model.ts'

// On the list page: a link to the admin page, for the user `admin` only.
export const AdminLink = ui.view({
  render: () =>
    ui.nav({ class: 'mx-auto max-w-xl px-4 pt-2 text-sm' }, [
      ui.query(
        me,
        {},
        {
          ready: (user) => (user.name === 'admin' ? ui.a({ href: ui.link(admin, null), class: 'underline' }, ['Admin']) : null),
          failed: { Unauthorized: () => null, Unexpected: () => null },
        },
      ),
    ]),
})

export const AdminBoard = ui.view({
  route: admin,
  render: () =>
    ui.main({ class: 'mx-auto max-w-xl space-y-6 px-4 py-12' }, [
      ui.h1({ class: 'text-3xl font-bold' }, ['Admin']),
      ui.query(
        listUsers,
        {},
        {
          ready: (users) =>
            ui.table({ class: 'w-full text-left' }, [
